def slugify(s):
    """Lowercase, trim, collapse runs of non-alphanumerics to single '-', no leading/trailing '-'."""
    s = s.lower().strip()

    out = []
    prev_dash = False

    for ch in s:
        if ch.isalnum():
            out.append(ch)
            prev_dash = False
        elif not prev_dash:
            out.append("-")
            prev_dash = True

    return "".join(out).strip("-")
